import React, { useEffect, useState, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import api from '../../services/api';
import OrderViewModal from './OrderViewModal';

const STATUS_LABELS = {
  pending:              'Customer Orders (New/Rework)',
  design_pending:       'Design Pending',
  design_uploaded:      'Confirm Design',
  design_confirmed:     'Design Confirmed',
  customer_pending:     'Customer Confirmation Pending',
  customer_confirmed:   'Assign to Development',
  assigned_development: 'Assigned to Development',
  under_processing:     'Under Processing',
  completed:            'Completed',
  cancelled:            'Cancelled',
};

const fmt = (dateStr) => {
  if (!dateStr) return '—';
  const d = new Date(dateStr);
  return isNaN(d) ? dateStr : d.toLocaleDateString('en-IN');
};

const OrderWorkflow = () => {
  const { status } = useParams();
  const [orders, setOrders]         = useState([]);
  const [viewOrderId, setViewOrderId] = useState(null);

  const load = useCallback(async () => {
    try {
      if (status === 'pending') {
        const { data } = await api.get('https://localhost:7113/api/order/GetReworkOrder');
        setOrders(data);
      } else {
        const { data } = await api.get(`/orders${status ? `?status=${status}` : ''}`);
        setOrders(data);
      }
    } catch {}
  }, [status]);

  useEffect(() => { load(); }, [load]);

  const renderBody = () => {
    switch (status) {
      case 'pending':
        return (
          <table className="table table-hover mb-0">
            <thead className="table-light">
              <tr>
                <th>Order #</th>
                <th>Customer</th>
                <th>Date</th>
                <th>Design</th>
                <th>Quantity</th>
                <th>Delivery Date</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {orders.length === 0 ? (
                <tr><td colSpan={7} className="text-center py-4 text-muted">No orders</td></tr>
              ) : orders.map(o => (
                <tr key={o.order_ID}>
                  <td><strong>{o.order_Number}</strong></td>
                  <td>{o.customer_Name}</td>
                  <td>{fmt(o.order_Date)}</td>
                  <td>{o.design || '—'}</td>
                  <td>{o.quantity || '—'}</td>
                  <td>{fmt(o.delivery_Date)}</td>
                  <td>
                    <button
                      className="btn btn-sm btn-primary"
                      onClick={() => setViewOrderId(o.order_ID)}
                    >
                      View
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        );

      case 'rework_requested':
      default:
        return (
          <div className="text-center py-5 text-muted">No orders to display.</div>
        );
    }
  };

  return (
    <div>
      <h5 className="fw-bold mb-4">{STATUS_LABELS[status] || 'Orders'}</h5>

      <div className="card">
        <div className="card-body p-0">
          <div className="table-responsive">
            {renderBody()}
          </div>
        </div>
      </div>

      {/* Order View + Action Modal */}
      <OrderViewModal
        orderId={viewOrderId}
        onClose={() => setViewOrderId(null)}
        onOrderUpdated={load}
      />
    </div>
  );
};

export default OrderWorkflow;
